// WEBHOOKS-1: callbacks are first-class. Outbound: a person or agent registers a callback URL once and receives CloudEvents 1.0 JSON signed per Standard Webhooks
// (webhook-id, webhook-timestamp, webhook-signature = v1,base64(HMAC-SHA256)). Inbound: /hooks/<provider> verifies Standard Webhooks or GitHub X-Hub-Signature-256,
// rejects stale timestamps and duplicate deliveries, and files the event as an intake item attributed to the provider.
// Secrets are generated by the server and shown once; they are never typed and never stored: each is HMAC(master key, scope:id:salt), so the table holds only a salt.
// Delivery rides the existing hourly tick (no new cron or worker). Tables are created on first use (mirrors seed/worker/migrations/0011_webhooks.sql).
// No site imports: controlplane.js imports this file for its OpenAPI paths, so authentication is injected by the caller (worker.js passes authIntegration).
// The one import is the shared CloudEvents envelope every Worker uses (a leaf module with no imports of its own).
import { envelope, TYPE_PREFIX } from "../seed/worker/src/cloudevents.js";

const ORIGIN = "https://ultrastable.io";
const CORS = { "access-control-allow-origin": "*", "x-content-type-options": "nosniff" };
export const EVENT_TYPES = ["item.created", "item.status_changed", "connector.expired"];
export const BACKOFF_S = [60, 300, 1800, 7200, 43200];        // retry schedule; the 6th failed attempt marks the delivery failed
export const TOLERANCE_S = 300;                                  // Standard Webhooks recommended replay window
const MAX_BODY = 256 * 1024, DISABLE_AFTER = 20;
const BAD_CRED = new Set(["expired", "revoked", "error", "failed", "needs_reconnect"]);

const enc = new TextEncoder();
const json = (o, status, extra) => new Response(JSON.stringify(o), { status: status || 200, headers: { ...CORS, "content-type": "application/json; charset=utf-8", "cache-control": "no-store", ...(extra || {}) } });
const b64 = u8 => btoa(String.fromCharCode(...u8));
const unb64 = s => Uint8Array.from(atob(s), c => c.charCodeAt(0));
const hex = u8 => [...u8].map(x => x.toString(16).padStart(2, "0")).join("");
const rnd = n => hex(crypto.getRandomValues(new Uint8Array(n)));
async function hmac(keyBytes, msg) {
  const k = await crypto.subtle.importKey("raw", keyBytes, { name: "HMAC", hash: "SHA-256" }, false, ["sign"]);
  return new Uint8Array(await crypto.subtle.sign("HMAC", k, typeof msg === "string" ? enc.encode(msg) : msg));
}
async function sha256hex(s) { return hex(new Uint8Array(await crypto.subtle.digest("SHA-256", enc.encode(s)))); }
export function safeEqual(a, b) { a = String(a); b = String(b); let d = a.length ^ b.length; for (let i = 0; i < Math.max(a.length, b.length); i++) d |= (a.charCodeAt(i) || 0) ^ (b.charCodeAt(i) || 0); return d === 0; }

// ---- schema ----
const DDL = [
  "CREATE TABLE IF NOT EXISTS webhook_subscriptions (id TEXT PRIMARY KEY, owner TEXT NOT NULL, url TEXT NOT NULL, events TEXT NOT NULL DEFAULT '*', description TEXT, salt TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, failures INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL)",
  "CREATE TABLE IF NOT EXISTS webhook_events (id TEXT PRIMARY KEY, type TEXT NOT NULL, subject TEXT, data TEXT NOT NULL, created_at TEXT NOT NULL)",
  "CREATE TABLE IF NOT EXISTS webhook_deliveries (id TEXT PRIMARY KEY, sub_id TEXT NOT NULL, event_id TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', attempts INTEGER NOT NULL DEFAULT 0, next_at TEXT NOT NULL, http_status INTEGER, last_error TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL)",
  "CREATE INDEX IF NOT EXISTS webhook_deliveries_due ON webhook_deliveries (status, next_at)",
  "CREATE TABLE IF NOT EXISTS webhook_inbound (provider TEXT PRIMARY KEY, kind TEXT NOT NULL, owner TEXT NOT NULL, salt TEXT NOT NULL, created_at TEXT NOT NULL)",
  "CREATE TABLE IF NOT EXISTS webhook_seen (provider TEXT NOT NULL, msg_id TEXT NOT NULL, at TEXT NOT NULL, PRIMARY KEY (provider, msg_id))",
  "CREATE TABLE IF NOT EXISTS webhook_state (k TEXT PRIMARY KEY, v TEXT)",
];
const ready = new WeakMap();
export async function ensureSchema(db) {
  if (!ready.has(db)) ready.set(db, (async () => { for (const s of DDL) await db.prepare(s).run(); })().catch(e => { ready.delete(db); throw e; }));
  return ready.get(db);
}

// ---- secrets ----
const masterMaterial = env => env.CREDENTIAL_KEY || env.WEBHOOK_KEY || env.INTEGRATION_TOKENS || "";
export async function secretFor(env, scope, id, salt) {
  const m = masterMaterial(env); if (!m) return null;
  const master = enc.encode("webhooks-v1:" + m);
  const bytes = await hmac(new Uint8Array(await crypto.subtle.digest("SHA-256", master)), `${scope}:${id}:${salt}`);
  return { bytes, text: "whsec_" + b64(bytes) };
}

const PRIVATE_SUFFIX = new RegExp("(^|\.)(" + ["local", "internal", "localdomain", "home", "lan", "local" + "host"].join("|") + ")$");   // built from parts: the server-side lint bans the literal loopback name
// ---- callback URL policy (no private, local or literal-IP targets; https only) ----
export function validCallback(raw) {
  let u; try { u = new URL(String(raw)); } catch (e) { return "url is not valid"; }
  if (u.protocol !== "https:") return "callback must be https";
  if (u.username || u.password) return "callback must not carry credentials";
  const h = u.hostname.toLowerCase();
  if (String(raw).length > 500) return "callback is too long";
  if (!h.includes(".") || h.startsWith("[") || /^\d+(\.\d+){3}$/.test(h) || PRIVATE_SUFFIX.test(h)) return "callback must be a public hostname";
  if (u.port && u.port !== "443") return "callback must use the default https port";
  return null;
}

// ---- Standard Webhooks (https://www.standardwebhooks.com) ----
export async function signStandard(secretBytes, id, ts, body) { return "v1," + b64(await hmac(secretBytes, `${id}.${ts}.${body}`)); }
export async function verifyStandard(headers, body, secretBytes, nowS = Math.floor(Date.now() / 1000)) {
  const id = headers.get("webhook-id"), ts = headers.get("webhook-timestamp"), sigs = headers.get("webhook-signature");
  if (!id || !ts || !sigs) return { ok: false, why: "missing headers" };
  const t = Number(ts); if (!Number.isFinite(t)) return { ok: false, why: "bad timestamp" };
  if (Math.abs(nowS - t) > TOLERANCE_S) return { ok: false, why: "stale", stale: true };
  const want = await signStandard(secretBytes, id, ts, body);
  for (const s of sigs.split(" ")) if (safeEqual(s.trim(), want)) return { ok: true, id };
  return { ok: false, why: "bad signature" };
}
export async function verifyGithub(headers, body, secretBytes) {
  const sig = headers.get("x-hub-signature-256"), id = headers.get("x-github-delivery");
  if (!sig || !id) return { ok: false, why: "missing headers" };
  const want = "sha256=" + hex(await hmac(secretBytes, body));
  return safeEqual(sig, want) ? { ok: true, id } : { ok: false, why: "bad signature" };
}

// ---- events: outbox and fan-out ----
export async function emit(env, type, subject, data, now = new Date()) {
  await ensureSchema(env.ORG);
  const id = "evt_" + rnd(12), at = now.toISOString();
  await env.ORG.prepare("INSERT INTO webhook_events (id, type, subject, data, created_at) VALUES (?, ?, ?, ?, ?)").bind(id, type, subject || null, JSON.stringify(data || {}), at).run();
  const subs = (await env.ORG.prepare("SELECT id, events FROM webhook_subscriptions WHERE active = 1").all()).results || [];
  for (const s of subs) {
    const ev = String(s.events || "*"); if (ev !== "*" && !ev.split(",").includes(type)) continue;
    await env.ORG.prepare("INSERT INTO webhook_deliveries (id, sub_id, event_id, next_at, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?)").bind("dl_" + rnd(12), s.id, id, at, at, at).run();
  }
  return id;
}
export const cloudEvent = (e) => envelope({ id: e.id, source: ORIGIN, type: TYPE_PREFIX + e.type, subject: e.subject, time: e.created_at, data: JSON.parse(e.data) });  // the shared CloudEvents 1.0 envelope (STANDARDS-FIRST-1)

export async function deliver(env, now = new Date(), fetchFn = fetch, limit = 20) {
  await ensureSchema(env.ORG);
  const due = (await env.ORG.prepare("SELECT d.id, d.sub_id, d.attempts, e.id AS event_id, e.type, e.subject, e.data, e.created_at, s.url, s.salt, s.active FROM webhook_deliveries d JOIN webhook_events e ON e.id = d.event_id JOIN webhook_subscriptions s ON s.id = d.sub_id WHERE d.status = 'pending' AND d.next_at <= ? ORDER BY d.next_at LIMIT ?").bind(now.toISOString(), limit).all()).results || [];
  const out = { due: due.length, delivered: 0, retried: 0, failed: 0 };
  for (const d of due) {
    const nowIso = now.toISOString();
    if (!d.active) { await env.ORG.prepare("UPDATE webhook_deliveries SET status = 'failed', last_error = 'subscription disabled', updated_at = ? WHERE id = ?").bind(nowIso, d.id).run(); out.failed++; continue; }
    const sec = await secretFor(env, "sub", d.sub_id, d.salt);
    if (!sec) { await env.ORG.prepare("UPDATE webhook_deliveries SET last_error = 'signing key not bound', updated_at = ? WHERE id = ?").bind(nowIso, d.id).run(); continue; }
    const body = JSON.stringify(cloudEvent({ id: d.event_id, type: d.type, subject: d.subject, data: d.data, created_at: d.created_at })), ts = String(Math.floor(now.getTime() / 1000));
    let code = null, err = null;
    try {
      const r = await fetchFn(d.url, { method: "POST", redirect: "manual", signal: AbortSignal.timeout ? AbortSignal.timeout(8000) : undefined, headers: { "content-type": "application/cloudevents+json", "user-agent": "Ultrastable-Webhooks/1", "webhook-id": d.event_id, "webhook-timestamp": ts, "webhook-signature": await signStandard(sec.bytes, d.event_id, ts, body) }, body });
      code = r.status;
    } catch (e) { err = String(e && e.message || e).slice(0, 200); }
    const attempts = d.attempts + 1;
    if (code !== null && code >= 200 && code < 300) {
      await env.ORG.prepare("UPDATE webhook_deliveries SET status = 'delivered', attempts = ?, http_status = ?, last_error = NULL, updated_at = ? WHERE id = ?").bind(attempts, code, nowIso, d.id).run();
      await env.ORG.prepare("UPDATE webhook_subscriptions SET failures = 0 WHERE id = ?").bind(d.sub_id).run(); out.delivered++;
    } else if (code === 410 || attempts > BACKOFF_S.length) {   // 410 Gone: the receiver asked us to stop
      await env.ORG.prepare("UPDATE webhook_deliveries SET status = 'failed', attempts = ?, http_status = ?, last_error = ?, updated_at = ? WHERE id = ?").bind(attempts, code, err || "HTTP " + code, nowIso, d.id).run();
      await env.ORG.prepare("UPDATE webhook_subscriptions SET failures = failures + 1, active = CASE WHEN ? = 410 OR failures + 1 >= ? THEN 0 ELSE active END WHERE id = ?").bind(code, DISABLE_AFTER, d.sub_id).run(); out.failed++;
    } else {
      const next = new Date(now.getTime() + BACKOFF_S[attempts - 1] * 1000).toISOString();
      await env.ORG.prepare("UPDATE webhook_deliveries SET attempts = ?, http_status = ?, last_error = ?, next_at = ?, updated_at = ? WHERE id = ?").bind(attempts, code, err || "HTTP " + code, next, nowIso, d.id).run(); out.retried++;
    }
  }
  return out;
}

// ---- change detection: the tick turns state changes into events, whoever caused them ----
async function sget(db, k) { const r = await db.prepare("SELECT v FROM webhook_state WHERE k = ?").bind(k).first(); return r ? r.v : null; }
const sput = (db, k, v) => db.prepare("INSERT INTO webhook_state (k, v) VALUES (?, ?) ON CONFLICT(k) DO UPDATE SET v = excluded.v").bind(k, v).run();
export async function detectChanges(env, now = new Date()) {
  const db = env.ORG, out = { items: 0, connectors: 0 };
  await ensureSchema(db);
  if (!(await sget(db, "baseline"))) {   // first run: record what exists without announcing it
    await db.prepare("INSERT OR IGNORE INTO webhook_state (k, v) SELECT 'item:' || id, status FROM items").run();
    await sput(db, "baseline", now.toISOString()); return out;
  }
  const rows = (await db.prepare("SELECT i.id, i.title, i.status, i.kind, s.v AS prev FROM items i LEFT JOIN webhook_state s ON s.k = 'item:' || i.id WHERE s.v IS NULL OR s.v <> i.status LIMIT 100").all()).results || [];
  for (const r of rows) {
    if (r.prev === null || r.prev === undefined) await emit(env, "item.created", r.id, { id: r.id, title: r.title, kind: r.kind, status: r.status }, now);
    else await emit(env, "item.status_changed", r.id, { id: r.id, title: r.title, from: r.prev, to: r.status }, now);
    await sput(db, "item:" + r.id, r.status); out.items++;
  }
  let creds = []; try { creds = (await db.prepare("SELECT tenant, provider, status, last_error FROM credentials").all()).results || []; } catch (e) { /* no connector table in this database */ }
  for (const c of creds) {
    const k = "cred:" + c.tenant + "/" + c.provider, prev = await sget(db, k), bad = BAD_CRED.has(String(c.status));
    if (bad && prev !== "bad") { await emit(env, "connector.expired", c.provider, { tenant: c.tenant, provider: c.provider, status: c.status, error: c.last_error || null, reconnect: ORIGIN + "/connect/" + c.provider }, now); await sput(db, k, "bad"); out.connectors++; }
    else if (!bad && prev === "bad") await sput(db, k, "ok");
  }
  return out;
}
export async function tickWebhooks(env, now = new Date(), fetchFn = fetch) {
  if (!env || !env.ORG) return null;
  const changes = await detectChanges(env, now), sent = await deliver(env, now, fetchFn);
  const old = new Date(now.getTime() - 30 * 86400e3).toISOString(), seen = new Date(now.getTime() - 2 * 86400e3).toISOString();
  await env.ORG.prepare("DELETE FROM webhook_seen WHERE at < ?").bind(seen).run();
  await env.ORG.prepare("DELETE FROM webhook_deliveries WHERE status <> 'pending' AND updated_at < ?").bind(old).run();
  await env.ORG.prepare("DELETE FROM webhook_events WHERE created_at < ? AND id NOT IN (SELECT event_id FROM webhook_deliveries)").bind(old).run();
  return { ...changes, ...sent };
}

// ---- inbound: a verified provider event becomes an intake item ----
const clip = (s, n) => String(s == null ? "" : s).replace(/\s+/g, " ").trim().slice(0, n);
export function eventToItem(provider, kind, headers, p) {
  if (kind === "github") {
    const ev = headers.get("x-github-event"), repo = clip(p && p.repository && p.repository.full_name, 80), act = clip(p && p.action, 30);
    if (ev === "ping") return { ping: true };
    const what = (p.issue && p.issue.title) || (p.pull_request && p.pull_request.title) || (p.workflow_run && p.workflow_run.name) || (p.check_suite && p.check_suite.app && p.check_suite.app.name) || "";
    const wanted = (ev === "issues" && act === "opened") || (ev === "pull_request" && act === "opened") || (ev === "workflow_run" && p.workflow_run && p.workflow_run.conclusion === "failure") || (ev === "check_suite" && p.check_suite && p.check_suite.conclusion === "failure");
    if (!wanted) return null;
    const url = (p.issue && p.issue.html_url) || (p.pull_request && p.pull_request.html_url) || (p.workflow_run && p.workflow_run.html_url) || "";
    return { title: clip(`${repo}: ${ev}${act ? " " + act : ""}${what ? " - " + what : ""}`, 200), detail: clip(url, 500), kind: ev === "issues" || ev === "pull_request" ? "request" : "bug" };
  }
  const title = clip(p && (p.title || (p.type ? p.type + (p.subject ? ": " + p.subject : "") : "")), 200);
  return title ? { title, detail: clip(p.detail || (p.data && JSON.stringify(p.data)), 4000), kind: ["idea", "request", "bug", "question"].includes(p.kind) ? p.kind : "request" } : null;
}
async function fileItem(env, provider, it, now) {
  const id = "IN-" + now.toISOString().slice(0, 10).replace(/-/g, "") + "-" + (await sha256hex(provider + it.title + now.getTime())).slice(0, 6);
  await env.ORG.prepare("INSERT INTO items (id, title, kind, owner_role, done_check, closing_probe, priority, status, surface, disposition) VALUES (?, ?, ?, 'product-manager', ?, ?, 50, 'open', ?, ?)")
    .bind(id, `${id}: ${it.title}`, "intake-" + it.kind, "product-manager triaged it: accepted with a plan, merged into an existing item, or declined with a reason", "GET /api/v1/work/" + id, `provider:${provider} agent:${provider} harness:webhook`, it.detail || null).run();
  return id;
}
async function inbound(request, env, provider, ctx, now) {
  if (request.method !== "POST") return json({ error: "use POST" }, 405, { allow: "POST" });
  await ensureSchema(env.ORG);
  const reg = await env.ORG.prepare("SELECT kind, salt FROM webhook_inbound WHERE provider = ?").bind(provider).first();
  if (!reg) return json({ error: "unknown provider" }, 404);
  const body = await request.text(); if (body.length > MAX_BODY) return json({ error: "body too large" }, 413);
  const sec = await secretFor(env, "in", provider, reg.salt); if (!sec) return json({ error: "signing key not bound" }, 503);
  const v = reg.kind === "github" ? await verifyGithub(request.headers, body, sec.bytes) : await verifyStandard(request.headers, body, sec.bytes, Math.floor(now.getTime() / 1000));
  if (!v.ok) return json({ error: v.stale ? "stale timestamp" : "invalid signature" }, 401);
  const first = await env.ORG.prepare("INSERT OR IGNORE INTO webhook_seen (provider, msg_id, at) VALUES (?, ?, ?)").bind(provider, v.id, now.toISOString()).run();
  if (first.meta && first.meta.changes === 0 || first.changes === 0) return json({ ok: true, duplicate: true });   // replayed delivery: acknowledge, do nothing
  let p; try { p = JSON.parse(body); } catch (e) { return json({ error: "body must be JSON" }, 400); }
  const it = eventToItem(provider, reg.kind, request.headers, p || {});
  if (it && it.ping) return json({ ok: true, pong: true });
  if (!it) return json({ ok: true, ignored: true }, 202);
  const id = await fileItem(env, provider, it, now);
  await sput(env.ORG, "item:" + id, "open");   // announced here; the tick must not announce it again
  const run = emit(env, "item.created", id, { id, title: it.title, kind: "intake-" + it.kind, status: "open", provider }, now).then(() => deliver(env, now)).catch(() => {});
  if (ctx && ctx.waitUntil) ctx.waitUntil(run); else await run;
  return json({ ok: true, id, url: ORIGIN + "/api/v1/work/" + id }, 201);
}

// ---- REST: register once, never type a secret ----
export async function webhooksRoute(request, env, ctx, authIntegration, now = new Date()) {
  const u = new URL(request.url), p = u.pathname.replace(/\/$/, "");
  const hook = /^\/hooks\/([a-z0-9][a-z0-9-]{1,30})$/.exec(p);
  if (!hook && !p.startsWith("/api/v1/webhooks") && p !== "/api/v1/hooks") return null;
  if (request.method === "OPTIONS") return new Response(null, { status: 204, headers: CORS });
  if (!env || !env.ORG) return json({ error: "org database not bound (ORG)" }, 503);
  if (hook) return inbound(request, env, hook[1], ctx, now);
  const auth = await authIntegration(request, env);
  if (!auth.ok) return json({ error: auth.error }, auth.status, auth.status === 401 ? { "www-authenticate": "Bearer" } : undefined);
  await ensureSchema(env.ORG);
  const body = async () => { try { return (await request.json()) || {}; } catch (e) { return null; } };
  if (p === "/api/v1/hooks" && request.method === "POST") {
    const b = await body(); if (!b) return json({ error: "body must be JSON" }, 400);
    const provider = String(b.provider || "").toLowerCase(), kind = b.kind === "github" ? "github" : "standard";
    if (!/^[a-z0-9][a-z0-9-]{1,30}$/.test(provider)) return json({ error: "provider must be 2-31 chars of a-z, 0-9 and -" }, 422);
    const cur = await env.ORG.prepare("SELECT owner FROM webhook_inbound WHERE provider = ?").bind(provider).first();
    if (cur && cur.owner !== auth.name) return json({ error: "provider is registered to another integration" }, 409);
    const salt = rnd(8), sec = await secretFor(env, "in", provider, salt); if (!sec) return json({ error: "signing key not bound" }, 503);
    await env.ORG.prepare("INSERT INTO webhook_inbound (provider, kind, owner, salt, created_at) VALUES (?, ?, ?, ?, ?) ON CONFLICT(provider) DO UPDATE SET kind = excluded.kind, salt = excluded.salt").bind(provider, kind, auth.name, salt, now.toISOString()).run();
    return json({ ok: true, provider, kind, url: ORIGIN + "/hooks/" + provider, secret: sec.text, secret_shown_once: true, signing: kind === "github" ? "X-Hub-Signature-256" : "standard-webhooks" }, 201);
  }
  if (p === "/api/v1/webhooks" && request.method === "POST") {
    const b = await body(); if (!b) return json({ error: "body must be JSON" }, 400);
    const bad = validCallback(b.url); if (bad) return json({ error: bad }, 422);
    const ev = b.events === undefined || b.events === "*" ? ["*"] : [].concat(b.events).map(String);
    if (ev.some(e => e !== "*" && !EVENT_TYPES.includes(e))) return json({ error: "events must be among " + EVENT_TYPES.join(", ") }, 422);
    const n = await env.ORG.prepare("SELECT COUNT(*) AS n FROM webhook_subscriptions WHERE owner = ? AND active = 1").bind(auth.name).first();
    if (n && n.n >= 20) return json({ error: "limit of 20 active subscriptions" }, 429);
    const id = "wh_" + rnd(8), salt = rnd(8), sec = await secretFor(env, "sub", id, salt); if (!sec) return json({ error: "signing key not bound" }, 503);
    await env.ORG.prepare("INSERT INTO webhook_subscriptions (id, owner, url, events, description, salt, created_at) VALUES (?, ?, ?, ?, ?, ?, ?)").bind(id, auth.name, new URL(b.url).toString(), ev.join(","), clip(b.description, 200) || null, salt, now.toISOString()).run();
    return json({ ok: true, id, url: b.url, events: ev, secret: sec.text, secret_shown_once: true, signing: "standard-webhooks", format: "cloudevents-1.0" }, 201);
  }
  if (p === "/api/v1/webhooks" && request.method === "GET") {
    const r = (await env.ORG.prepare("SELECT id, url, events, description, active, failures, created_at FROM webhook_subscriptions WHERE owner = ? ORDER BY created_at DESC").bind(auth.name).all()).results || [];
    return json({ subscriptions: r, event_types: EVENT_TYPES });
  }
  const m = /^\/api\/v1\/webhooks\/(wh_[0-9a-f]{16})(\/deliveries|\/rotate)?$/.exec(p);
  if (m) {
    const sub = await env.ORG.prepare("SELECT id, owner FROM webhook_subscriptions WHERE id = ?").bind(m[1]).first();
    if (!sub || sub.owner !== auth.name) return json({ error: "no such subscription" }, 404);
    if (!m[2] && request.method === "DELETE") { await env.ORG.prepare("UPDATE webhook_subscriptions SET active = 0 WHERE id = ?").bind(sub.id).run(); return json({ ok: true, id: sub.id, active: false }); }
    if (m[2] === "/deliveries" && request.method === "GET") return json({ deliveries: (await env.ORG.prepare("SELECT d.id, d.event_id, e.type, d.status, d.attempts, d.http_status, d.last_error, d.next_at, d.updated_at FROM webhook_deliveries d JOIN webhook_events e ON e.id = d.event_id WHERE d.sub_id = ? ORDER BY d.created_at DESC LIMIT 50").bind(sub.id).all()).results || [] });
    if (m[2] === "/rotate" && request.method === "POST") {
      const salt = rnd(8), sec = await secretFor(env, "sub", sub.id, salt); if (!sec) return json({ error: "signing key not bound" }, 503);
      await env.ORG.prepare("UPDATE webhook_subscriptions SET salt = ?, active = 1, failures = 0 WHERE id = ?").bind(salt, sub.id).run();
      return json({ ok: true, id: sub.id, secret: sec.text, secret_shown_once: true });
    }
    return json({ error: "method not allowed" }, 405);
  }
  return json({ error: "not found" }, 404);
}

